import java.util.TreeSet; class Solution { public boolean containsNearbyAlmostDuplicate(int[] nums, int indexDiff, int valueDiff) { TreeSet<Long> set = new TreeSet<>(); for (int i = 0; i < nums.length; i++) { long val = (long) nums[i]; Long floor = set.floor(val + valueDiff); Long ceil = set.ceiling(val - valueDiff); if ((floor != null && floor >= val) || (ceil != null && ceil <= val)) { return true; } set.add(val); if (i >= indexDiff) { set.remove((long) nums[i - indexDiff]); } } return false; } }